"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[3729],{60112:e=>{e.exports=JSON.parse('{"tag":{"label":"AI","permalink":"/docs/tags/ai","allTagsPath":"/docs/tags","count":19,"items":[{"id":"AI Agents/About AI agents","title":"About AI agents","description":"The DataGOL AI agents empowers business users and engineers to efficiently analyze and visualize data through a suite of specialized AI agents. These agents act as intelligent assistants, guiding users through the data exploration process and accelerating insights.","permalink":"/docs/AI Agents/about-ai-agent"},{"id":"AI Agents/AI Search agent","title":"AI Search agent","description":"What is AI Search agent?","permalink":"/docs/AI Agents/ai-search-agent"},{"id":"AI Agents/Atlassian agent","title":"Atlassian Agent (Jira + Confluence)","description":"Overview","permalink":"/docs/AI Agents/atlassian-agent"},{"id":"AI Agents/Business Intelligence (BI) agent - (Chart agent)","title":"Business Intelligence (BI) agent - (Chart agent)","description":"About Chart agent","permalink":"/docs/AI Agents/business-intelligence-BI-agent-Chart-agent"},{"id":"AI Agents/Creating and sharing Custom agent publicly","title":"Creating and sharing Custom agent publicly","description":"Public Agent Sharing feature allows you to extend the power of your custom AI agents beyond your internal team, providing a seamless, interactive experience for your clients and stakeholders. Public sharing allows you to deploy Custom agents that external users (clients, partners, or the general public) can interact without needing to log in.","permalink":"/docs/AI Agents/creating-sharing-custom-agent"},{"id":"AI Agents/Custom agent","title":"Custom agent","description":"What is Custom Agent?","permalink":"/docs/AI Agents/custom-agent"},{"id":"AI Agents/Data Analytics and Visualization Engineer (DAVE)","title":"Data Analytics and Visualization Engineer (DAVE)","description":"What is D.A.V.E.?","permalink":"/docs/AI Agents/data-analytics-visualization-engineer"},{"id":"AI Agents/Data Cleaning (DC) agent","title":"Data Cleaning (DC) agent","description":"The DC agent helps users to clean and organize their data within a workbook. This includes tasks like deduplication, normalization, data imputation, and filtering.","permalink":"/docs/AI Agents/data-cleaning-agent-DCA-agent"},{"id":"AI Agents/Data Conversation agent (DCA)","title":"Data Conversation agent (DCA)","description":"What is DCA (Data Conversation Agent)?","permalink":"/docs/AI Agents/data-conversation-agent"},{"id":"AI Agents/Data Science agent","title":"Data Science agent","description":"What is Data Science agent?","permalink":"/docs/AI Agents/data-science-agent"},{"id":"AI Agents/Fellow agent","title":"Fellow agent","description":"The DataGOL Fellow agent acts as your personal intelligent layer, ensuring that meeting data is never lost and is always ready to serve your specific project needs. Here is how the agent improves your daily workflow:","permalink":"/docs/AI Agents/fellow-agent-ai"},{"id":"AI Agents/Financial Deep Research agent","title":"Financial Deep Research agent","description":"The Financial Deep Research Agent is a powerful multi-agent architecture designed to perform in-depth, comprehensive financial analysis on any organization. It operates by delegating complex research tasks to a team of specialized, independent AI agents, ensuring a thorough and data-driven report.","permalink":"/docs/AI Agents/financial-deep-research-agent"},{"id":"AI Agents/GRC agent","title":"GRC agent","description":"Understanding GRC","permalink":"/docs/AI Agents/grc-agent"},{"id":"AI Agents/HubSpot agent","title":"HubSpot agent","description":"The HubSpot agent is an AI-powered tool designed to interact with your HubSpot CRM. It allows you to retrieve information and perform actions directly within your HubSpot environment by using natural language commands.","permalink":"/docs/AI Agents/hubspot-agent"},{"id":"AI Agents/Jira agent","title":"Jira agent","description":"What is the Jira agent?","permalink":"/docs/AI Agents/jira-agent"},{"id":"AI Agents/Knowledge Graph agent","title":"Knowledge Graph agent","description":"What is a Knowledge Graph agent?","permalink":"/docs/AI Agents/knowledge-graph-agent"},{"id":"AI Agents/RAG agent","title":"RAG agent","description":"What is a RAG agent?","permalink":"/docs/AI Agents/rag-agent"},{"id":"AI Agents/Salesforce agent","title":"Salesforce agent","description":"What is the Salesforce agent?","permalink":"/docs/AI Agents/salesforce-agent"},{"id":"AI Agents/SQL agent","title":"SQL agent","description":"About SQL agent","permalink":"/docs/AI Agents/sql-agent"}],"unlisted":false}}')}}]);